module array_restorer ( input clk, input [31:0] M [0:7][0:7], input [2:0] n, output reg [31:0] result [0:7] ); reg [31:0] temp_result [0:7]; reg [31:0] temp0, temp1, temp2, temp3, temp4, temp5, temp6, temp7; reg [2:0] j0, j1, j2, j3, j4, j5, j6, j7; reg [2:0] k0, k1, k2, k3, k4, k5, k6, k7; reg [31:0] A0, B0, C0, A1, B1, C1, A2, B2, C2, A3, B3, C3, A4, B4, C4, A5, B5, C5, A6, B6, C6, A7, B7, C7; always @(posedge clk) begin j0 = (0+1) % n; k0 = (0+2) % n; A0 = M[0][j0]; B0 = M[0][k0]; C0 = M[j0][k0]; temp0 = (A0 * B0) / C0; temp_result[0] = (temp0 >> 1) << 16; j1 = (1+1) % n; k1 = (1+2) % n; A1 = M[1][j1]; B1 = M[1][k1]; C1 = M[j1][k1]; temp1 = (A1 * B1) / C1; temp_result[1] = (temp1 >> 1) << 16; j2 = (2+1) % n; k2 = (2+2) % n; A2 = M[2][j2]; B2 = M[2][k2]; C2 = M[j2][k2]; temp2 = (A2 * B2) / C2; temp_result[2] = (temp2 >> 1) << 16; j3 = (3+1) % n; k3 = (3+2) % n; A3 = M[3][j3]; B3 = M[3][k3]; C3 = M[j3][k3]; temp3 = (A3 * B3) / C3; temp_result[3] = (temp3 >> 1) << 16; j4 = (4+1) % n; k4 = (4+2) % n; A4 = M[4][j4]; B4 = M[4][k4]; C4 = M[j4][k4]; temp4 = (A4 * B4) / C4; temp_result[4] = (temp4 >> 1) << 16; j5 = (5+1) % n; k5 = (5+2) % n; A5 = M[5][j5]; B5 = M[5][k5]; C5 = M[j5][k5]; temp5 = (A5 * B5) / C5; temp_result[5] = (temp5 >> 1) << 16; j6 = (6+1) % n; k6 = (6+2) % n; A6 = M[6][j6]; B6 = M[6][k6]; C6 = M[j6][k6]; temp6 = (A6 * B6) / C6; temp_result[6] = (temp6 >> 1) << 16; j7 = (7+1) % n; k7 = (7+2) % n; A7 = M[7][j7]; B7 = M[7][k7]; C7 = M[j7][k7]; temp7 = (A7 * B7) / C7; temp_result[7] = (temp7 >> 1) << 16; result <= temp_result; end endmodule